/// Commit every staged bandaid piece (daemon / hub / stock) as one
/// transaction, then restart bridgething.service once. Bandaid pushes
/// (`OtaKind::Daemon`, `OtaKind::BuiltinWebapp`) stage at stream
/// completion (phase reaches `Writing`/100, the daemon does NOT restart); the
/// companion sends `OtaActivate` after the final piece to swap them all
/// live with a single restart. Image OTAs never use this -- they reboot
/// at write completion.
///
/// `expected` is the set of `update_id`s the companion staged this
/// batch. The daemon errors the activate if its staged set does not
/// match exactly, which guards a desync where a daemon crash dropped the
/// in-memory staged set between staging and activation.
@Serializable
data class OtaActivate (
	val expected: List<String>
)

/// Half-open byte range the daemon's range proxy asks the companion
/// to serve. Mirrors HTTP `Range: bytes=start-end` semantics: `start`
/// inclusive, `length` bytes. The proxy caps the multi-range count at
/// the daemon edge (loopback) - companions see whatever swupdate's
/// delta downloader emits. Offsets are u32 because OTA artifacts are
/// bounded at 4 GiB end-to-end (matches `OtaBegin.expected_size`).
@Serializable
data class RangeSpec (
	val start: UInt,
	val length: UInt
)

/// Daemon asks the pinned companion to serve byte ranges from an asset
/// it should have cached (and can refetch from `OtaBegin.update_url_base`
/// on cache miss). Triggered by an inbound HTTP-Range request from
/// libswupdate's delta downloader hitting the daemon's loopback proxy.
/// Range count is bounded daemon-side; companions just serve whatever
/// arrives.
@Serializable
data class OtaAssetRange (
	val updateId: String,
	val asset: String,
	val ranges: List<RangeSpec>
)

/// Daemon-side cancel for an in-flight range request: libcurl gave up
/// (timeout, OTA failed, daemon is shutting down). Companion stops the
/// fragment stream for `request_id` and frees any resources it held
/// open.
@Serializable
data class OtaAssetRangeAbandon (
	@Serializable(with = MsgpackUuidSerializer::class) val requestId: UUID
)

/// Domain-error response to `OtaAssetRange`: the companion can't serve
/// the requested ranges (asset unknown for this `update_id`, refetch
/// from `update_url_base` failed, sha mismatch on refetched asset, etc).
/// The daemon surfaces this to libswupdate as a `502 Bad Gateway` and
/// the running OTA fails.
@Serializable
data class OtaAssetRangeRejected (
	val reason: String
)

/// Resolved range the companion is about to serve. `start` and `length`
/// echo the corresponding `RangeSpec`; the bytes follow in the reply's
/// `TransferBody`.
@Serializable
data class RangePart (
	val start: UInt,
	val length: UInt
)

/// Successful response to `OtaAssetRange`. The companion has the asset
/// (or refetched it from `update_url_base`) and serves the resolved
/// ranges in `body`: small results inline, larger ones as a fragment
/// stream whose offsets are stream-relative (0..sum of part lengths,
/// parts concatenated in declaration order - the daemon's HTTP-Range
/// writer maps them to absolute positions via `parts`). `total_size` is
/// the asset's full byte length (for `Content-Range` totals).
@Serializable
data class OtaAssetRangeReply (
	val totalSize: UInt,
	val parts: List<RangePart>,
	val body: TransferBody
)

/// What the streamed bytes are going to be applied as.
///
/// `Image` streams a `.swu` through libswupdate + slot flip + reboot.
/// `Daemon` streams a fresh aarch64 daemon binary, atomic-rotates on
/// the bandaid bind-mount, restarts the service. `BuiltinWebapp`
/// streams a zip bundle of hub or stock, validates the manifest id is
/// one of the reserved built-ins, atomic-rotates the bundle dir on the
/// bandaid bind-mount, restarts the service. `InstalledWebapp` streams
/// a zip bundle of a third-party (non-reserved) webapp and installs it
/// into the writable registry; it neither stages on the bandaid nor
/// restarts, and is never part of an `OtaActivate` batch.
///
/// Companions key reboot expectations off this: image means the device
/// power-cycles; daemon and builtin-webapp mean the daemon process
/// restarts and the gateway link drops and reconnects; installed-webapp
/// applies in place with no restart, and the terminal signal is the
/// `WebappInstalled` event (or an `OtaError`).
@Serializable
enum class OtaKind(val string: String) {
	@SerialName("image")
	Image("image"),
	@SerialName("daemon")
	Daemon("daemon"),
	@SerialName("builtinWebapp")
	BuiltinWebapp("builtinWebapp"),
	@SerialName("installedWebapp")
	InstalledWebapp("installedWebapp"),
}

/// Handle to a fragment stream, embedded in the typed message that
/// opens a transfer (a pull reply or a push begin). The bytes travel
/// out-of-band as `TransferFragment` events keyed by `id`; the
/// transfer completes when `total_size` bytes have arrived. For pull
/// replies `id` is the originating request id.
@Serializable
data class TransferRef (
	@Serializable(with = MsgpackUuidSerializer::class) val id: UUID,
	val totalSize: UInt,
	val sha256: String? = null
)

/// Companion-initiated OTA: opens or resumes a streaming push of an
/// update artifact identified by its sha256. The daemon responds with
/// `OtaBeginAck { resume_from_offset }` (the byte offset the first
/// `TransferFragment` should start at, 0 for fresh pushes) or
/// `OtaBeginRejected { reason }`.
///
/// `kind` selects the backend. See `OtaKind`.
///
/// `update_id` is the sha256 of the artifact, hex-encoded. Content-
/// addressed so resume across daemon restarts and retries-after-failure
/// both work without companion-side state to track. `transfer.id` is
/// minted per attempt and only correlates the fragment stream; the
/// daemon binds it to the `update_id`-keyed partial, so a reconnect
/// with a fresh transfer id still resumes the same bytes.
///
/// `update_url_base` is image-kind only: the server prefix the companion
/// may refetch the .zck delta from on cache miss while serving range
/// requests during the Writing phase. Ignored for non-image kinds.
@Serializable
data class OtaBegin (
	val kind: OtaKind,
	val updateId: String,
	val updateUrlBase: String? = null,
	val transfer: TransferRef
)

/// Successful response to `OtaBegin`. `resume_from_offset` is the byte
/// offset the first `TransferFragment` should start at: 0 for fresh pushes, or
/// the daemon's recovered partial length for a resume.
@Serializable
data class OtaBeginAck (
	val resumeFromOffset: UInt
)

/// Domain-error response to `OtaBegin`: the daemon refuses to start
/// or resume this push (already-running OTA, conflicting in-flight
/// update_id with mismatched size/sha, budget exhausted).
@Serializable
data class OtaBeginRejected (
	val reason: String
)

/// Terminal error from the OTA orchestrator. After an `OtaError` the
/// orchestrator is back to idle and a fresh `OtaBegin` may be sent.
@Serializable
enum class OtaErrorCode(val string: String) {
	/// Companion sent fragments for an `update_id` that was never begun
	/// (or was abandoned mid-stream).
	@SerialName("unknownUpdate")
	UnknownUpdate("unknownUpdate"),
	/// A fragment's offset did not match the daemon's `received`.
	@SerialName("offsetMismatch")
	OffsetMismatch("offsetMismatch"),
	/// Streamed total's sha256 did not match `OtaBegin.transfer.sha256`.
	@SerialName("hashMismatch")
	HashMismatch("hashMismatch"),
	/// Streamed total's byte length did not match `OtaBegin.transfer.total_size`.
	@SerialName("sizeMismatch")
	SizeMismatch("sizeMismatch"),
	/// `CancelUpdate` arrived during a cancelable phase.
	@SerialName("cancelled")
	Cancelled("cancelled"),
	/// libswupdate rejected the .swu (parse / handler / I/O failure).
	@SerialName("writeFailed")
	WriteFailed("writeFailed"),
	/// Slot-flip / try-counter reset failed after a successful write.
	@SerialName("confirmFailed")
	ConfirmFailed("confirmFailed"),
	/// Anything else (transfer-cache I/O, internal channel close, etc.).
	@SerialName("internal")
	Internal("internal"),
}

@Serializable
data class OtaError (
	val code: OtaErrorCode,
	val msg: String
)

/// Stage of the OTA orchestrator. The phase set is shared between
/// kinds, with non-image kinds emitting a subset.
///
/// Image: `Streaming` -> `Verifying` -> `Writing` (libswupdate to slot)
/// -> `Confirming` (try-counter reset) -> `Reboot`.
///
/// Daemon and BuiltinWebapp: `Streaming` -> `Verifying` -> `Writing`,
/// where `Writing`/100 means the piece is validated and staged on the
/// bandaid (not yet live). The atomic rotate and the single `systemctl
/// restart` happen later, on `OtaActivate`, which emits the terminal
/// `Reboot` for the whole batch. `Confirming` is image-only.
///
/// InstalledWebapp: `Streaming` -> `Verifying` -> `Writing`/0 while the
/// bundle installs into the writable registry. There is no `Writing`/100,
/// no `Confirming`, and no `Reboot`; the terminal signal is the
/// `WebappInstalled` event (or an `OtaError`).
@Serializable
enum class OtaPhase(val string: String) {
	@SerialName("streaming")
	Streaming("streaming"),
	@SerialName("verifying")
	Verifying("verifying"),
	@SerialName("writing")
	Writing("writing"),
	@SerialName("confirming")
	Confirming("confirming"),
	@SerialName("reboot")
	Reboot("reboot"),
}

/// Per-phase progress tick. `percent` is 0-100 within the current
/// phase, not the overall flow. `eta_ms` is best-effort remaining time
/// for the phase when the orchestrator can compute it.
@Serializable
data class OtaProgress (
	val phase: OtaPhase,
	val percent: UByte,
	val etaMs: UInt? = null
)

